"""Embedded test images for the multimodal quality items.

Generated once with Pillow at development time and committed as base64 so a
quality run never depends on local fonts, network assets or rebuild steps.
Every image is deterministic: same bytes, same grading target, forever.
"""

from __future__ import annotations

CHART_B64: str = ''

SIGN_B64: str = ''

SHAPES_B64: str = ''

FRAME_B64S: tuple[str, ...] = (
    '',
    '',
    '',
    '',)


def data_url(raw: str) -> str:
    return f'data:image/png;base64,{raw}'
